    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = {x: sum(v == x for row in grid for v in row) for x in range(1, 10)}
    main = max((x for x in counts if x not in (2, 4)), key=lambda x: counts[x])
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    for i, (r1, c1) in enumerate(markers):
        for r2, c2 in markers[i + 1:]:
            if r1 == r2:
                lo, hi = sorted((c1, c2))
                for c in range(lo, hi + 1):
                    g[r1][c] = main
            elif c1 == c2:
                lo, hi = sorted((r1, r2))
                for r in range(lo, hi + 1):
                    g[r][c1] = main
    # Fill single-cell holes inside straight runs.
    for r in range(h):
        for c in range(1, w - 1):
            if g[r][c] == 0 and g[r][c-1] != 0 and g[r][c-1] == g[r][c+1]:
                g[r][c] = g[r][c-1]
    for c in range(w):
        for r in range(1, h - 1):
            if g[r][c] == 0 and g[r-1][c] != 0 and g[r-1][c] == g[r+1][c]:
                g[r][c] = g[r-1][c]
    # A 4 continues the adjoining stem to the border and trims its tail
    # back to the nearest junction.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 4:
                continue
            if r and g[r-1][c] not in (0, 2, 4):
                color = g[r-1][c]
                g[r][c] = color
                for rr in range(r + 1, h):
                    g[rr][c] = color
                junction = r - 1
                while junction > 0:
                    if (c and g[junction][c-1] == color) or (c+1 < w and g[junction][c+1] == color):
                        break
                    junction -= 1
                for rr in range(junction):
                    if g[rr][c] == color:
                        g[rr][c] = 0
            elif c and g[r][c-1] not in (0, 2, 4):
                color = g[r][c-1]
                for cc in range(c, w):
                    g[r][cc] = color
            elif c+1 < w and g[r][c+1] not in (0, 2, 4):
                color = g[r][c+1]
                for cc in range(c + 1):
                    g[r][cc] = color
            elif r+1 < h and g[r+1][c] not in (0, 2, 4):
                color = g[r+1][c]
                for rr in range(r):
                    g[rr][c] = color
    return g
